// <auto-generated>
// Campground.Shared — compiled into each Campground plugin as internal code.
// Edit it in AHouseOfBards/Campground-Coordination/shared, never inside a plugin.
// </auto-generated>
#nullable enable

using System;
using System.Collections.Generic;
using System.IO;
using System.Text;
using System.Threading.Tasks;
using Campground.Shared.Network;
using Campground.Shared.Registry;
using MediaBrowser.Controller;
using MediaBrowser.Controller.Configuration;
using MediaBrowser.Common.Net;
using Microsoft.AspNetCore.Builder;
using Microsoft.AspNetCore.Hosting;
using Microsoft.AspNetCore.Http;
using Microsoft.AspNetCore.Http.Features;
using Microsoft.Extensions.DependencyInjection;
using Microsoft.Extensions.Hosting;
using Microsoft.Extensions.Logging;
using Microsoft.Extensions.Primitives;
using Microsoft.Net.Http.Headers;

namespace Campground.Shared.Injection
{
    /// <summary>Wires the coordinator into a plugin.</summary>
    internal static class CampgroundInjection
    {
        /// <summary>
        /// Call from the plugin's <c>IPluginServiceRegistrator.RegisterServices</c>. Registers this plugin's
        /// scripts and adds the middleware through an <see cref="IStartupFilter"/> (ordinary public API, as
        /// Bonfire does). Every plugin adds it; only the owner acts.
        /// </summary>
        internal static void AddCampgroundInjection(this IServiceCollection services, string pluginId, params ScriptRegistration[] scripts)
        {
            foreach (var s in scripts)
            {
                InjectionCoordinator.Register(s);
            }

            services.AddSingleton<IStartupFilter>(new CampgroundStartupFilter(pluginId));
        }
    }

    internal sealed class CampgroundStartupFilter : IStartupFilter
    {
        private readonly string _pluginId;

        internal CampgroundStartupFilter(string pluginId) => _pluginId = pluginId;

        public Action<IApplicationBuilder> Configure(Action<IApplicationBuilder> next)
            => app =>
            {
                app.UseMiddleware<CampgroundIndexMiddleware>(_pluginId);

                // Joins this host's generation first, so the candidacy below is recorded under it (issue #33).
                if (app.ApplicationServices.GetService<IHostApplicationLifetime>() is { } lifetime)
                {
                    CampgroundLifetime.Register(_pluginId, lifetime);
                }

                // Candidacy is recorded only once the middleware is really in the pipeline (issue #5).
                InjectionCoordinator.RecordCandidate(_pluginId, CampgroundShared.Version);
                next(app);
            };
    }

    /// <summary>
    /// Adds every Campground plugin's scripts to index.html as it's served, without touching the file.
    /// Buffers the downstream response (composes with the File Transformation plugin and anything else that
    /// edits the document) — the design Bonfire arrived at in 1.4.4.
    /// </summary>
    internal sealed class CampgroundIndexMiddleware
    {
        private static readonly string[] NegotiationHeaders =
        {
            HeaderNames.AcceptEncoding,
            HeaderNames.IfNoneMatch,
            HeaderNames.IfModifiedSince,
            HeaderNames.Range,
            HeaderNames.IfRange,
        };

        private readonly RequestDelegate _next;
        private readonly string _pluginId;
        private readonly ILogger<CampgroundIndexMiddleware> _logger;

        public CampgroundIndexMiddleware(RequestDelegate next, string pluginId, ILogger<CampgroundIndexMiddleware> logger)
        {
            _next = next;
            _pluginId = pluginId;
            _logger = logger;
        }

        public async Task Invoke(HttpContext context, IServerConfigurationManager serverConfig, IServerApplicationHost appHost)
        {
            // The runtime and head files (0.10.0). Every copy answers, owner or not, so the first 0.10.0 middleware
            // in the pipeline serves them; an older copy before it passes the request through.
            if (IsCampgroundFile(context.Request.Path.Value))
            {
                if (await TryServeFile(context, serverConfig).ConfigureAwait(false))
                {
                    return;
                }
            }

            if (!InjectionCoordinator.ClaimOwnership(_pluginId) || !ShouldHandle(context, serverConfig, appHost, out var baseUrl))
            {
                await _next(context).ConfigureAwait(false);
                return;
            }

            InjectionCoordinator.RecordMiddlewareActive();

            // Reset on every handled request. Only the served path used to clear it, so one transient failure
            // stayed on every dashboard until the server restarted, under a document that was being served
            // correctly (Bonfire shipped exactly that, and fixed it the same way).
            InjectionCoordinator.ClearError();
            var tags = InjectionCoordinator.ActiveTags();
            var runtime = Emergency.EmergencyDisable.IsCampgroundDisabled ? null : InjectionCoordinator.Runtime();
            if (tags.Count == 0 && runtime == null)
            {
                await _next(context).ConfigureAwait(false);
                return;
            }

            var originalBody = context.Features.Get<IHttpResponseBodyFeature>();
            if (originalBody == null)
            {
                InjectionCoordinator.RecordError("the response has no body feature to capture.");
                await _next(context).ConfigureAwait(false);
                return;
            }

            byte[] produced;
            using (var captured = new MemoryStream())
            {
                var capture = new StreamResponseBodyFeature(captured);
                var saved = Suspend(context.Request);
                context.Features.Set<IHttpResponseBodyFeature>(capture);
                try
                {
                    await _next(context).ConfigureAwait(false);
                    await capture.CompleteAsync().ConfigureAwait(false);
                }
                finally
                {
                    context.Features.Set(originalBody);
                    Restore(context.Request, saved);
                }

                produced = captured.ToArray();
            }

            if (context.Response.HasStarted)
            {
                InjectionCoordinator.RecordError("the index.html response had already started, so nothing could be added.");
                _logger.LogWarning("Campground: index.html response had already started; served unchanged.");
                if (produced.Length > 0)
                {
                    await context.Response.Body.WriteAsync(produced, context.RequestAborted).ConfigureAwait(false);
                }

                return;
            }

            if (!IsTransformable(context.Response))
            {
                await PassThrough(context, produced).ConfigureAwait(false);
                return;
            }

            string html;
            try
            {
                var document = Encoding.UTF8.GetString(produced);
                if (!IndexHtml.Apply(document, baseUrl, tags, runtime, asFiles: true, out html))
                {
                    // Nothing changed: either every fragment is already current (healthy: an older on-disk
                    // patch, or File Transformation adding the same tag), or there was nowhere to put them.
                    // Only the second is a failure, and it was silent: the dashboard said nothing while no
                    // plugin's script reached a single browser.
                    if (!IndexHtml.HasAnchors(document))
                    {
                        InjectionCoordinator.RecordError("index.html has no <head> or </body> to add scripts to; served unchanged.");
                    }

                    await PassThrough(context, produced).ConfigureAwait(false);
                    return;
                }
            }
            catch (OperationCanceledException)
            {
                // The client went away. Not a failure, and not worth a dashboard warning.
                return;
            }
            catch (Exception ex)
            {
                InjectionCoordinator.RecordError(ex.Message);
                _logger.LogWarning(ex, "Campground: could not add scripts to index.html; serving it unchanged.");
                await PassThrough(context, produced).ConfigureAwait(false);
                return;
            }

            var bytes = Encoding.UTF8.GetBytes(html);
            context.Response.ContentType = "text/html; charset=utf-8";
            context.Response.ContentLength = bytes.Length;
            context.Response.Headers.Remove(HeaderNames.ETag);
            context.Response.Headers.Remove(HeaderNames.LastModified);
            context.Response.Headers[HeaderNames.CacheControl] = "no-cache, no-store, must-revalidate";
            context.Response.Headers[HeaderNames.Pragma] = "no-cache";
            context.Response.Headers[HeaderNames.Expires] = "0";
            InjectionCoordinator.RecordServed();
            await context.Response.Body.WriteAsync(bytes, context.RequestAborted).ConfigureAwait(false);
        }

        // Cheap test first: this runs on every request in the server.
        private static bool IsCampgroundFile(string? path)
            => path != null
               && path.EndsWith(".js", StringComparison.OrdinalIgnoreCase)
               && path.IndexOf("/Campground/", StringComparison.OrdinalIgnoreCase) != -1;

        /// <summary>
        /// Answers <c>/Campground/runtime.js</c> and <c>/Campground/head/&lt;id&gt;.js</c>, with or without the
        /// base URL. Returns false (and leaves the request alone) for anything else under /Campground/.
        /// </summary>
        private static async Task<bool> TryServeFile(HttpContext context, IServerConfigurationManager serverConfig)
        {
            if (!HttpMethods.IsGet(context.Request.Method) && !HttpMethods.IsHead(context.Request.Method))
            {
                return false;
            }

            var path = context.Request.Path.Value!;
            var baseUrl = string.Empty;
            try
            {
                baseUrl = JellyfinNetworkSettings.NormalizeBaseUrl(serverConfig.GetNetworkConfiguration().BaseUrl);
            }
            catch (Exception)
            {
                // Unprefixed match below still covers the default install.
            }

            var rel = Strip(path, baseUrl) ?? Strip(path, string.Empty);
            if (rel == null)
            {
                return false;
            }

            string? script = null;
            var current = false;
            if (rel.Equals(IndexHtml.RuntimePath, StringComparison.OrdinalIgnoreCase))
            {
                // The highest version offered, as the inline form always served (0.5.0). Off under the brake.
                var runtime = Emergency.EmergencyDisable.IsCampgroundDisabled ? null : InjectionCoordinator.Runtime();
                if (runtime is { } rt)
                {
                    script = rt.Script;
                    current = string.Equals(context.Request.Query["v"].ToString(), rt.Version, StringComparison.Ordinal);
                }
            }
            else if (rel.StartsWith(IndexHtml.HeadPathPrefix, StringComparison.OrdinalIgnoreCase))
            {
                var id = Uri.UnescapeDataString(rel.Substring(IndexHtml.HeadPathPrefix.Length, rel.Length - IndexHtml.HeadPathPrefix.Length - 3));
                foreach (var t in InjectionCoordinator.ActiveTags())
                {
                    if (string.Equals(t.HeadId, id, StringComparison.Ordinal) && IndexHtml.HeadScriptBody(t) is { } body)
                    {
                        script = body;
                        current = string.Equals(context.Request.Query["v"].ToString(), IndexHtml.ContentVersion(body), StringComparison.Ordinal);
                        break;
                    }
                }
            }
            else
            {
                return false;
            }

            if (script == null)
            {
                context.Response.StatusCode = StatusCodes.Status404NotFound;
                context.Response.Headers[HeaderNames.CacheControl] = "no-cache, no-store, must-revalidate";
                return true;
            }

            var bytes = Encoding.UTF8.GetBytes(script);
            context.Response.StatusCode = StatusCodes.Status200OK;
            context.Response.ContentType = "application/javascript; charset=utf-8";
            context.Response.ContentLength = bytes.Length;
            context.Response.Headers["X-Content-Type-Options"] = "nosniff";

            // The URL carries the version, so a matching one can be cached. A stale one (an index.html cached from
            // before an update) gets today's code and isn't kept.
            context.Response.Headers[HeaderNames.CacheControl] = current ? "public, max-age=86400" : "no-cache";
            if (!HttpMethods.IsHead(context.Request.Method))
            {
                await context.Response.Body.WriteAsync(bytes, context.RequestAborted).ConfigureAwait(false);
            }

            return true;
        }

        private static string? Strip(string path, string baseUrl)
        {
            var prefix = baseUrl.TrimEnd('/');
            return path.StartsWith(prefix + "/Campground/", StringComparison.OrdinalIgnoreCase) ? path.Substring(prefix.Length) : null;
        }

        private static bool IsTransformable(HttpResponse r)
            => r.StatusCode == StatusCodes.Status200OK
               && !r.Headers.ContainsKey(HeaderNames.ContentEncoding)
               && (r.ContentType?.StartsWith("text/html", StringComparison.OrdinalIgnoreCase) ?? false);

        private static async Task PassThrough(HttpContext context, byte[] produced)
        {
            if (!context.Response.HasStarted && produced.Length > 0)
            {
                await context.Response.Body.WriteAsync(produced, context.RequestAborted).ConfigureAwait(false);
            }
        }

        private static List<KeyValuePair<string, StringValues>> Suspend(HttpRequest request)
        {
            var saved = new List<KeyValuePair<string, StringValues>>();
            foreach (var name in NegotiationHeaders)
            {
                if (request.Headers.TryGetValue(name, out var value))
                {
                    saved.Add(new(name, value));
                    request.Headers.Remove(name);
                }
            }

            return saved;
        }

        private static void Restore(HttpRequest request, List<KeyValuePair<string, StringValues>> saved)
        {
            foreach (var h in saved)
            {
                request.Headers[h.Key] = h.Value;
            }
        }

        private static bool ShouldHandle(HttpContext context, IServerConfigurationManager serverConfig, IServerApplicationHost appHost, out string baseUrl)
        {
            baseUrl = string.Empty;
            if (!HttpMethods.IsGet(context.Request.Method) || string.IsNullOrEmpty(context.Request.Path.Value))
            {
                return false;
            }

            try
            {
                var n = serverConfig.GetNetworkConfiguration();
                // Step aside only when Jellyfin itself will redirect to HTTPS (RequireHttps AND listening with HTTPS).
                if (n.RequireHttps && !context.Request.IsHttps && appHost.ListenWithHttps)
                {
                    return false;
                }

                baseUrl = JellyfinNetworkSettings.NormalizeBaseUrl(n.BaseUrl);
            }
            catch (Exception)
            {
                // Unprefixed match below still covers the default install.
            }

            var path = context.Request.Path.Value!;
            return IsIndexPath(path, baseUrl) || IsIndexPath(path, null);
        }

        internal static bool IsIndexPath(string path, string? baseUrl)
        {
            var web = (baseUrl ?? string.Empty).TrimEnd('/') + "/web";
            return path.Equals(web + "/", StringComparison.OrdinalIgnoreCase)
                || path.Equals(web + "/index.html", StringComparison.OrdinalIgnoreCase);
        }
    }
}
